const urls={afis:'https://skybrary.aero/articles/aerodrome-flight-information-service-afis',fis:'https://skybrary.aero/articles/flight-information-service-fis',panpan:'https://skybrary.aero/articles/pan-pan',mayday:'https://skybrary.aero/articles/mayday',lostcomm:'https://skybrary.aero/articles/radio-communication-failure',missed:'https://skybrary.aero/articles/missed-approach',sidstar:'https://skybrary.aero/articles/standard-instrument-departure-sid',star:'https://skybrary.aero/articles/standard-terminal-arrival-route-star',phr:'https://skybrary.aero/articles/standard-phraseology',ifrvfr:'https://skybrary.aero/articles/instrument-flight-rules-ifr'};
